    style6.textContent = '#SpicyLyricsPage [data-simplebar] {\n  position: relative;\n  flex-direction: column;\n  flex-wrap: wrap;\n  justify-content: flex-start;\n  align-content: flex-start;\n  align-items: flex-start;\n}\n\n#SpicyLyricsPage .simplebar-wrapper {\n  overflow: hidden;\n  width: inherit;\n  height: inherit;\n  max-width: inherit;\n  max-height: inherit;\n}\n\n#SpicyLyricsPage .simplebar-mask {\n  direction: inherit;\n  position: absolute;\n  overflow: hidden;\n  padding: 0;\n  margin: 0;\n  left: 0;\n  top: 0;\n  bottom: 0;\n  right: 0;\n  width: auto !important;\n  height: auto !important;\n  z-index: 0;\n}\n\n#SpicyLyricsPage .simplebar-offset {\n  direction: inherit !important;\n  box-sizing: inherit !important;\n  resize: none !important;\n  position: absolute;\n  top: 0;\n  left: 0;\n  bottom: 0;\n  right: 0;\n  padding: 0;\n  margin: 0;\n  -webkit-overflow-scrolling: touch;\n}\n\n#SpicyLyricsPage .simplebar-content-wrapper {\n  direction: inherit;\n  box-sizing: border-box !important;\n  position: relative;\n  display: block;\n  height: 100%; /* Required for horizontal native scrollbar to not appear if parent is taller than natural height */\n  width: auto;\n  max-width: 100%; /* Not required for horizontal scroll to trigger */\n  max-height: 100%; /* Needed for vertical scroll to trigger */\n  overflow: auto;\n  scrollbar-width: none;\n  -ms-overflow-style: none;\n  will-change: transform;\n  transform: translate3d(0px, 0px, 0px);\n}\n\n#SpicyLyricsPage .simplebar-content-wrapper::-webkit-scrollbar,\n#SpicyLyricsPage .simplebar-hide-scrollbar::-webkit-scrollbar {\n  display: none;\n  width: 0;\n  height: 0;\n}\n\n#SpicyLyricsPage .simplebar-content:before,\n#SpicyLyricsPage .simplebar-content:after {\n  content: " ";\n  display: table;\n}\n\n#SpicyLyricsPage .simplebar-placeholder {\n  max-height: 100%;\n  max-width: 100%;\n  width: 100%;\n  pointer-events: none;\n}\n\n#SpicyLyricsPage .simplebar-height-auto-observer-wrapper {\n  box-sizing: inherit !important;\n  height: 100%;\n  width: 100%;\n  max-width: 1px;\n  position: relative;\n  float: left;\n  max-height: 1px;\n  overflow: hidden;\n  z-index: -1;\n  padding: 0;\n  margin: 0;\n  pointer-events: none;\n  flex-grow: inherit;\n  flex-shrink: 0;\n  flex-basis: 0;\n}\n\n#SpicyLyricsPage .simplebar-height-auto-observer {\n  box-sizing: inherit;\n  display: block;\n  opacity: 0;\n  position: absolute;\n  top: 0;\n  left: 0;\n  height: 1000%;\n  width: 1000%;\n  min-height: 1px;\n  min-width: 1px;\n  overflow: hidden;\n  pointer-events: none;\n  z-index: -1;\n}\n\n#SpicyLyricsPage .simplebar-track {\n  z-index: 1;\n  position: absolute;\n  right: 0;\n  bottom: 0;\n  pointer-events: none;\n  overflow: hidden;\n}\n\n#SpicyLyricsPage [data-simplebar].simplebar-dragging {\n  pointer-events: none;\n  -webkit-touch-callout: none;\n  -webkit-user-select: none;\n  -ms-user-select: none;\n  user-select: none;\n}\n\n#SpicyLyricsPage [data-simplebar].simplebar-dragging .simplebar-content {\n  pointer-events: none;\n  -webkit-touch-callout: none;\n  -webkit-user-select: none;\n  -ms-user-select: none;\n  user-select: none;\n}\n\n#SpicyLyricsPage [data-simplebar].simplebar-dragging .simplebar-track {\n  pointer-events: all;\n}\n\n#SpicyLyricsPage .simplebar-scrollbar {\n  position: absolute;\n  left: 0;\n  right: 0;\n  min-height: 10px;\n}\n\n.simplebar-scrollbar:before {\n  position: absolute;\n  content: "";\n  background: var(--Simplebar-Scrollbar-Color) !important;\n  border-radius: 7px;\n  left: 2px;\n  right: 2px;\n  opacity: 0;\n  transition: opacity 0.2s 0.5s linear !important;\n}\n\n#SpicyLyricsPage .simplebar-scrollbar.simplebar-visible:before {\n  opacity: 0.5 !important;\n  transition-delay: 0s !important;\n  transition-duration: 0s !important;\n}\n\n#SpicyLyricsPage .simplebar-track.simplebar-vertical {\n  top: 0;\n  width: 11px;\n}\n\n#SpicyLyricsPage .simplebar-scrollbar:before {\n  top: 2px;\n  bottom: 2px;\n  left: 2px;\n  right: 2px;\n}\n\n#SpicyLyricsPage .simplebar-track.simplebar-horizontal {\n  left: 0;\n  height: 11px;\n}\n\n#SpicyLyricsPage .simplebar-track.simplebar-horizontal .simplebar-scrollbar {\n  right: auto;\n  left: 0;\n  top: 0;\n  bottom: 0;\n  min-height: 0;\n  min-width: 10px;\n  width: auto;\n}\n\n/* Rtl support */\n#SpicyLyricsPage [data-simplebar-direction="rtl"] .simplebar-track.simplebar-vertical {\n  right: auto;\n  left: 0;\n}\n\n#SpicyLyricsPage .simplebar-dummy-scrollbar-size {\n  direction: rtl;\n  position: fixed;\n  opacity: 0;\n  visibility: hidden;\n  height: 500px;\n  width: 500px;\n  overflow-y: hidden;\n  overflow-x: scroll;\n  -ms-overflow-style: scrollbar !important;\n}\n\n#SpicyLyricsPage .simplebar-dummy-scrollbar-size > div {\n  width: 200%;\n  height: 200%;\n  margin: 10px 0;\n}\n\n#SpicyLyricsPage .ScrollbarScrollable .simplebar-track {\n  transition: opacity 0.2s linear !important;\n  opacity: 1;\n}\n\n#SpicyLyricsPage .ScrollbarScrollable .simplebar-track.simplebar-vertical {\n  right: 5px;\n}\n\n#SpicyLyricsPage .ScrollbarScrollable .simplebar-track.simplebar-horizontal {\n  bottom: 5px;\n}\n\n#SpicyLyricsPage .ScrollbarScrollable.hide-scrollbar .simplebar-track {\n  opacity: 0;\n}\n\n#SpicyLyricsPage [data-simplebar]:not(.simplebar-dragging) .simplebar-content-wrapper {\n  scroll-behavior: smooth !important;\n}\n\n#SpicyLyricsPage\n  [data-simplebar]:not(.simplebar-dragging)\n  .simplebar-content-wrapper.InstantScroll {\n  scroll-behavior: auto !important;\n}\n';
